// PRform's service worker.
//
// Hand-written rather than generated by next-pwa or workbox, for two reasons:
// it is small enough to read in one sitting, and the caching decisions here are
// about an app that shows one teenager's sleep data — which is not a decision
// to delegate to a plugin's defaults.
//
// ── What is deliberately NOT cached ─────────────────────────────────────────
//
// Page HTML. Every page in this app is personalized and server-rendered behind
// a session, so a cached page is one athlete's dashboard sitting on disk. On a
// shared laptop — a team room, a school library, a sibling's iPad — the next
// person to open the app offline would be shown it. So navigations are
// network-only, with a branded offline page as the fallback, and nothing
// personal is ever written to the cache.
//
// That makes this an offline *shell* in the honest sense: the app tells you it
// is offline instead of lying with yesterday's numbers. A sleep plan that is a
// day stale is not a lesser version of the truth, it is the wrong bedtime.
//
// API responses. Same reasoning, more so.
//
// What IS cached is the immutable build output — /_next/static/*, fonts, icons
// — which is content-hashed, identical for everyone, and the difference
// between the app opening instantly and it opening in three seconds.

const VERSION = "prform-v1";
const STATIC_CACHE = `${VERSION}-static`;
const OFFLINE_URL = "/offline.html";

/**
 * Precached at install so the offline page is available the first time the
 * network is not. Kept to exactly the things needed to render it — a long
 * precache list is a long install, and an install that fails leaves no worker
 * at all.
 */
const PRECACHE_URLS = [OFFLINE_URL, "/icons/icon-192.png"];

self.addEventListener("install", (event) => {
  event.waitUntil(
    caches
      .open(STATIC_CACHE)
      .then((cache) => cache.addAll(PRECACHE_URLS))
      // Take over immediately. The alternative — waiting for every tab to
      // close — means a fix to this file can sit undeployed for days on a
      // phone that never closes its tabs.
      .then(() => self.skipWaiting()),
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) =>
        Promise.all(keys.filter((key) => !key.startsWith(VERSION)).map((key) => caches.delete(key))),
      )
      .then(() => self.clients.claim()),
  );
});

/** Build output and static assets: content-hashed, so safe to serve from cache. */
function isImmutableAsset(url) {
  return (
    url.pathname.startsWith("/_next/static/") ||
    url.pathname.startsWith("/icons/") ||
    url.pathname.startsWith("/fonts/") ||
    /\.(?:woff2?|ttf|otf|png|jpe?g|svg|webp|ico)$/i.test(url.pathname)
  );
}

self.addEventListener("fetch", (event) => {
  const { request } = event;

  // Anything that changes state is none of this worker's business.
  if (request.method !== "GET") return;

  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;

  // Never touch the API. Responses are per-session and often per-second.
  if (url.pathname.startsWith("/api/")) return;

  if (request.mode === "navigate") {
    event.respondWith(
      fetch(request).catch(async () => {
        const cache = await caches.open(STATIC_CACHE);
        const offline = await cache.match(OFFLINE_URL);
        return (
          offline ??
          new Response("You're offline.", {
            status: 503,
            headers: { "Content-Type": "text/plain" },
          })
        );
      }),
    );
    return;
  }

  if (isImmutableAsset(url)) {
    event.respondWith(
      caches.match(request).then((cached) => {
        if (cached) return cached;
        return fetch(request).then((response) => {
          // Only cache a genuinely successful, same-origin response. An opaque
          // or errored one cached here would be served forever.
          if (response.ok && response.type === "basic") {
            const copy = response.clone();
            caches.open(STATIC_CACHE).then((cache) => cache.put(request, copy));
          }
          return response;
        });
      }),
    );
  }
});

// ── Push ────────────────────────────────────────────────────────────────────

self.addEventListener("push", (event) => {
  // A push event that shows no notification is, on most browsers, a permission
  // the user eventually loses — repeated silent pushes get the site's
  // permission revoked. So every branch here ends in showNotification, even the
  // one where the payload made no sense.
  let payload = {};
  try {
    payload = event.data ? event.data.json() : {};
  } catch {
    payload = {};
  }

  const title = payload.title || "PRform";
  const body = payload.body || "Open PRform to see tonight's plan.";
  const url = payload.url || "/dashboard";

  event.waitUntil(
    self.registration.showNotification(title, {
      body,
      // Monochrome, matching the design system. Android renders `badge` as a
      // small monochrome glyph in the status bar and `icon` as the large one.
      icon: "/icons/icon-192.png",
      badge: "/icons/icon-badge.png",
      // Same tag replaces rather than stacks, so a re-sent morning message
      // updates the one already on the lock screen instead of contradicting it.
      tag: payload.tag || "prform",
      renotify: Boolean(payload.tag),
      data: { url },
      // These arrive at bedtime and at wake-up. Letting the OS decide whether
      // to make noise is the right call for both.
      requireInteraction: false,
    }),
  );
});

self.addEventListener("notificationclick", (event) => {
  event.notification.close();
  const target = (event.notification.data && event.notification.data.url) || "/dashboard";

  event.waitUntil(
    self.clients.matchAll({ type: "window", includeUncontrolled: true }).then((clients) => {
      // Focus a tab that is already open rather than stacking another one. An
      // athlete tapping the morning notification five days running should not
      // end up with five copies of the app open.
      for (const client of clients) {
        if ("focus" in client) {
          client.navigate(target);
          return client.focus();
        }
      }
      return self.clients.openWindow(target);
    }),
  );
});

/**
 * The browser rotated this device's subscription out from under us.
 *
 * It happens without warning — a browser update, a key rotation on the push
 * service, an eviction. Without this handler the athlete's notifications
 * silently stop and neither they nor we find out until someone asks why the
 * app went quiet. Re-subscribing here and posting the new endpoint is the only
 * chance to repair it, because no page may be open when this fires.
 */
self.addEventListener("pushsubscriptionchange", (event) => {
  event.waitUntil(
    (async () => {
      try {
        const applicationServerKey =
          (event.oldSubscription && event.oldSubscription.options.applicationServerKey) ||
          (await fetch("/api/push/status")
            .then((r) => r.json())
            .then((d) => d.publicKey && urlBase64ToUint8Array(d.publicKey)));
        if (!applicationServerKey) return;

        const subscription = await self.registration.pushManager.subscribe({
          userVisibleOnly: true,
          applicationServerKey,
        });
        await fetch("/api/push/subscribe", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ subscription: subscription.toJSON() }),
        });
      } catch (e) {
        // Nothing useful to do — no UI to show, no session guaranteed. The
        // client-side registrar re-subscribes next time the app is opened.
      }
    })(),
  );
});

/** VAPID keys travel as base64url; PushManager wants raw bytes. */
function urlBase64ToUint8Array(base64String) {
  const padding = "=".repeat((4 - (base64String.length % 4)) % 4);
  const base64 = (base64String + padding).replace(/-/g, "+").replace(/_/g, "/");
  const raw = self.atob(base64);
  const output = new Uint8Array(raw.length);
  for (let i = 0; i < raw.length; i++) output[i] = raw.charCodeAt(i);
  return output;
}
